from django.db import migrations, models


def normalizar_sexo(apps, schema_editor):
    """Converte valores antigos (M/F, macho/femea) para as novas opções."""
    Animal = apps.get_model('animais', 'Animal')
    mapa = {
        'm': 'Macho', 'macho': 'Macho',
        'f': 'Fêmea', 'femea': 'Fêmea', 'fêmea': 'Fêmea',
    }
    for animal in Animal.objects.all():
        novo = mapa.get((animal.sexo or '').strip().lower())
        if novo and novo != animal.sexo:
            animal.sexo = novo
            animal.save(update_fields=['sexo'])


